from qgis.core import (QgsFillSymbol, QgsGraduatedSymbolRenderer, QgsRendererRange,
                        QgsCategorizedSymbolRenderer, QgsRendererCategory, QgsLineSymbol,
                        QgsVectorLayer, QgsClassificationQuantile)

def find_exact(name):
    return next((l for l in project.mapLayers().values()
                 if isinstance(l, QgsVectorLayer) and l.name() == name), None)

def find_kw(kw):
    return [l for l in project.mapLayers().values()
            if isinstance(l, QgsVectorLayer) and kw.lower() in l.name().lower()]

# Style bati par classe potentiel
bat = find_exact('Potentiel solaire toiture')
if bat:
    cat_colors = [
        ('tres_faible', '#888888', 'Très faible (< 30)'),
        ('faible',      '#ffcc66', 'Faible (30-100)'),
        ('moyen',       '#ff9933', 'Moyen (100-300)'),
        ('fort',        '#ff6600', 'Fort (300-800)'),
        ('tres_fort',   '#cc1100', 'Très fort (> 800)')
    ]
    cats = []
    for value, color, label in cat_colors:
        sym = QgsFillSymbol.createSimple({
            'color': color, 'outline_color': '#333333', 'outline_width': '0.1'
        })
        cats.append(QgsRendererCategory(value, sym, label))
    bat.setRenderer(QgsCategorizedSymbolRenderer('classe_potentiel', cats))
    bat.triggerRepaint()

# Style routes discrètes
routes = find_exact('Routes (BD TOPO)')
if routes:
    sym = QgsLineSymbol.createSimple({'color': '#666666', 'width': '0.2'})
    from qgis.core import QgsSingleSymbolRenderer
    routes.setRenderer(QgsSingleSymbolRenderer(sym))
    routes.triggerRepaint()

# Ordre des couches : bati DEVANT, routes derriere, ortho/plan en bas
root = project.layerTreeRoot()
layers_ordered = []
seen_ids = set()

def add_l(l, visible=True):
    if l and l.id() not in seen_ids:
        seen_ids.add(l.id())
        layers_ordered.append((l, visible))

add_l(bat, True)
add_l(routes, True)
# Rasters basemap EN DERNIER (= rendu derriere)
for l in project.mapLayers().values():
    if not isinstance(l, QgsVectorLayer) and l.id() not in seen_ids:
        seen_ids.add(l.id())
        # Ortho visible par defaut, plan masque
        visible = 'ortho' in l.name().lower() or 'photo' in l.name().lower()
        layers_ordered.append((l, visible))

render_layers = [l for l, v in layers_ordered]
root.setCustomLayerOrder(render_layers)
root.setHasCustomLayerOrder(True)
for layer, visible in layers_ordered:
    node = root.findLayer(layer.id())
    if node:
        node.setItemVisibilityChecked(visible)

result['success'] = True
